import{_ as r,o,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const g=JSON.parse('{"title":"2021Q1 Ceph社区季度进展报告","description":"","frontmatter":{"title":"2021Q1 Ceph社区季度进展报告","date":"2021-03-01T00:00:00.000Z","updated":"2021-03-01T00:00:00.000Z","tags":["Ceph","社区动态","季度报告"],"categories":["季度总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/2021Q1_Ceph社区季度总结.md","filePath":"posts/2021/2021Q1_Ceph社区季度总结.md","lastUpdated":1780460162000}'),i={name:"posts/2021/2021Q1_Ceph社区季度总结.md"};function s(h,e,l,n,p,m){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="ceph-社区-2021q1-季度进展报告" tabindex="-1">Ceph 社区 2021Q1 季度进展报告 <a class="header-anchor" href="#ceph-社区-2021q1-季度进展报告" aria-label="Permalink to &quot;Ceph 社区 2021Q1 季度进展报告&quot;">​</a></h1><hr><h2 id="_1-本季度重点议题" tabindex="-1">1. 本季度重点议题 <a class="header-anchor" href="#_1-本季度重点议题" aria-label="Permalink to &quot;1. 本季度重点议题&quot;">​</a></h2><p>本季度 Ceph 社区围绕以下几个核心方向持续深入讨论：</p><p><strong>Crimson/SeaStore 新一代 OSD 开发</strong> Crimson OSD 和 SeaStore 存储引擎是本季度最活跃的开发方向，贯穿整个季度的多次周会。核心议题包括客户端请求序列化、并发优化、垃圾回收器改进以及单元测试体系建设。详见 <a href="/VideoSummary/posts/2021/Ceph_Crimson_2021-02-23.html">Ceph Crimson 2021-23</a>)、<a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStore_2021-03-10.html">Ceph Crimson SeaStore 2021-03-10</a>)、<a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStore_2021-03-17.html">Ceph Crimson SeaStore 2021-03-17</a>)、<a href="/VideoSummary/posts/2021/Ceph_Crimson_Seastore_2021-03-23.html">Ceph Crimson Seastore 2021-03-23</a>)。</p><p><strong>Pacific 版本发布冲刺</strong> Pacific 是本季度最重要的里程碑，多个会议中均提及 Pacific 的阻塞问题修复和发布准备工作。</p><p><strong>Orchestrator 与 Cephadm 多站点管理</strong> RGW 多站点配置、NFS 服务管理、HA RGW 架构设计等 Orchestrator 层面的功能在本季度密集讨论。</p><p><strong>BlueStore/OMAP 性能优化</strong> BlueStore 的 OMAP 性能瓶颈、RocksDB 代码路径优化、缓存管理改进是性能方向的核心议题。</p><p><strong>Teuthology 测试基础设施</strong> 本季度专门开展了多场 Teuthology 培训，覆盖框架介绍、测试开发和结果分析，反映社区对测试质量的重视。</p><hr><h2 id="_2-技术亮点" tabindex="-1">2. 技术亮点 <a class="header-anchor" href="#_2-技术亮点" aria-label="Permalink to &quot;2. 技术亮点&quot;">​</a></h2><h3 id="crimson-seastore" tabindex="-1">Crimson/SeaStore <a class="header-anchor" href="#crimson-seastore" aria-label="Permalink to &quot;Crimson/SeaStore&quot;">​</a></h3><ul><li><strong>PG 流水线并行性 PR</strong>：本季度完成测试，旨在提升 OSD 并发处理能力。详见 <a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStore_2021-03-10.html">Ceph Crimson SeaStore 2021-03-10</a>)。</li><li><strong>垃圾回收器重构</strong>：将 GC 从每个事务的内置操作改为独立并发任务，简化了 GC 状态机，预期解决之前观察到的崩溃问题。详见 <a href="/VideoSummary/posts/2021/Ceph_Crimson_Seastore_2021-03-23.html">Ceph Crimson Seastore 2021-03-23</a>)。</li><li><strong>Alien Store 性能改进</strong>：将 Alien Store 线程分散到不同 CPU 核心，改善多核利用率。</li><li><strong>消息传递接口优化</strong>：讨论并决定在 Crimson 中使用 <code>unique_ptr</code> 替代 <code>intrusive_ptr</code> 传递消息，提升内存安全性。详见 <a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStore_2021-03-17.html">Ceph Crimson SeaStore 2021-03-17</a>)。</li><li><strong>客户端请求序列化器单元测试</strong>：持续推进，确保请求持久化顺序与到达 OSD 的顺序一致。</li></ul><h3 id="bluestore-性能" tabindex="-1">BlueStore 性能 <a class="header-anchor" href="#bluestore-性能" aria-label="Permalink to &quot;BlueStore 性能&quot;">​</a></h3><ul><li><strong>动态 pen length PR合并</strong>：解决了对齐问题，实测性能有所提升。</li><li><strong>RocksDB 分配移除 PR</strong>（Gaby 提交）：从 RocksDB 中移除分配操作，性能改进效果良好。</li><li><strong>OMAP 基准测试工具</strong>：新增快速 OMAP 基准测试 PR，支持写入多对象和大量键的时间测量。详见 <a href="/VideoSummary/posts/2021/Ceph_Performance_Meeting_2021-03-11.html">Ceph Performance Meeting 2021-03-11</a>)、<a href="/VideoSummary/posts/2021/Ceph_Performance_Meeting_2021-03-25.html">Ceph Performance Meeting 2021-03-25</a>)。</li><li><strong>BlueFS Buffered I/O 优化</strong>：讨论了将 BlueFS buffered I/O 设置为 true 的影响，相关 PR 已关闭并评估。</li></ul><h3 id="rbd" tabindex="-1">RBD <a class="header-anchor" href="#rbd" aria-label="Permalink to &quot;RBD&quot;">​</a></h3><ul><li><strong>librbd I/O 路径代码走读</strong>：系统梳理了从 API 层到核心层的完整 I/O 路径，包括 QoS、独占锁、刷新状态机等可插拔层的设计。详见 <a href="/VideoSummary/posts/2021/Ceph_Code_Walkthroughs_-_Librbd_Part_2.html">Ceph Code Walkthroughs - Librbd Part 2</a>)。</li></ul><h3 id="orchestrator-cephadm" tabindex="-1">Orchestrator / Cephadm <a class="header-anchor" href="#orchestrator-cephadm" aria-label="Permalink to &quot;Orchestrator / Cephadm&quot;">​</a></h3><ul><li><strong>HA RGW 服务架构</strong>：提出将 HAProxy 和 Keepalived 拆分为两个独立服务，提升灵活性。详见 <a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-23.html">Ceph Orchestrator Meeting 2021-03-23</a>)。</li><li><strong>RGW 配置上移至 Orchestrator 层</strong>：统一管理 RGW 配置，避免 Rook 和 Cephadm 中的重复配置。详见 <a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-30.html">Ceph Orchestrator Meeting 2021-03-30</a>)。</li><li><strong>OSD unmanaged 服务整合</strong>：将所有非托管 OSD 整合到单一 OS 服务中。</li><li><strong>网络/子网配置集成</strong>：推进将网络和子网配置纳入服务规范（service spec）。</li></ul><h3 id="pacific-新特性-sage-weil-介绍" tabindex="-1">Pacific 新特性（Sage Weil 介绍） <a class="header-anchor" href="#pacific-新特性-sage-weil-介绍" aria-label="Permalink to &quot;Pacific 新特性（Sage Weil 介绍）&quot;">​</a></h3><ul><li>多文件系统支持、CephFS 异步链接操作</li><li>RGW S3 Select 和 Lua 脚本集成</li><li>新的内存分配器和内存跟踪机制</li><li>改进的 QoS 和分布式追踪框架</li><li>Cephadm 支持自动化升级和私有注册表认证</li></ul><p>详见 <a href="/VideoSummary/posts/2021/What_s_New_in_Pacific_Ceph_Release_-_Sage_Weil.html">What&#39;s New in Pacific Ceph Release - Sage Weil</a>)。</p><hr><h2 id="_3-重要决策与里程碑" tabindex="-1">3. 重要决策与里程碑 <a class="header-anchor" href="#_3-重要决策与里程碑" aria-label="Permalink to &quot;3. 重要决策与里程碑&quot;">​</a></h2><p><strong>Pacific 版本发布</strong> Pacific 预计于 2021 年 3 月发布，本季度多个会议均在推进阻塞问题的修复。<a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStor_OSD_2021-01-26.html">Ceph Crimson SeaStor OSD 2021-01-26</a>) 中提到修复了 ceph-adm 中被认定为 Pacific 发布阻塞点的问题。</p><p><strong>NFS v3 支持决策</strong><a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-11.html">Ceph Orchestrator Meeting 2021-03-11</a>) 中讨论是否完全移除对 NFS 版本 3 的支持，决定通过邮件列表征求社区意见后再定。</p><p><strong>消息传递压缩方案</strong><a href="/VideoSummary/posts/2021/Ceph_Developer_Monthly_2021-02-03.html">Ceph Developer Monthly 2021-02-03</a>) 中讨论了在 Messenger 层添加传输压缩的方案，决定在社区中进一步讨论，倾向于在数据负载层而非整个消息层进行压缩，以避免重复压缩开销。</p><p><strong>Teuthology 调度机制升级</strong> 新的基于 Beanstalkd 优先队列的调度机制正式引入，解决了旧机制中的优先级反转问题。详见 <a href="/VideoSummary/posts/2021/Teuthology_Internals_-_Overview_and_Scheduling.html">Teuthology Internals - Overview and Scheduling</a>)。</p><p><strong>Quincy 版本规划启动</strong> Sage Weil 在 Pacific 介绍中提到，Quincy 版本规划即将开始，目标发布时间为 2022 年 3 月。</p><hr><h2 id="_4-社区动态" tabindex="-1">4. 社区动态 <a class="header-anchor" href="#_4-社区动态" aria-label="Permalink to &quot;4. 社区动态&quot;">​</a></h2><p><strong>开发者月度会议</strong> 2021 年 2 月举办了开发者月度会议，讨论了跨服务指标共享、满载集群删除操作处理、消息传递压缩等跨组件议题。详见 <a href="/VideoSummary/posts/2021/Ceph_Developer_Monthly_2021-02-03.html">Ceph Developer Monthly 2021-02-03</a>)。</p><p><strong>Science Working Group</strong> 科学用户工作组于 3 月举行非正式讨论，参与者主要为管理大型 Ceph 集群的用户，讨论了 MDS 内存问题、Nautilus 到 Octopus 升级计划，以及 Cephadm 在大规模集群中的性能问题。会议还规划了 <strong>Ceph Month</strong> 活动，作为 Cephalocon 的线上替代形式。详见 <a href="/VideoSummary/posts/2021/Ceph_Science_Working_Group_2021-03-24.html">Ceph Science Working Group 2021-03-24</a>)。</p><p><strong>Google Summer of Code</strong><a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-16.html">Ceph Orchestrator Meeting 2021-03-16</a>) 中讨论了 GSoC 项目参与情况，社区成员将担任共同导师。</p><p><strong>Teuthology 培训系列</strong> 本季度专门开展了三场 Teuthology 培训，系统覆盖框架介绍、测试开发方法和测试结果分析，旨在降低新贡献者的测试门槛。详见 <a href="/VideoSummary/posts/2021/Teuthology_Training_-_Introduction.html">Teuthology Training - Introduction</a>)、<a href="/VideoSummary/posts/2021/Teuthology_Training_-_Developing_Tests.html">Teuthology Training - Developing Tests</a>)、<a href="/VideoSummary/posts/2021/Teuthology_Training_-_Analyzing_Test_Results.html">Teuthology Training - Analyzing Test Results</a>)。</p><p><strong>代码走读系列</strong> librbd 代码走读第二部分在本季度举行，会议内容上传至 Ceph YouTube 频道，供社区成员学习参考。</p><hr><h2 id="_5-下季度展望" tabindex="-1">5. 下季度展望 <a class="header-anchor" href="#_5-下季度展望" aria-label="Permalink to &quot;5. 下季度展望&quot;">​</a></h2><p>基于本季度的讨论内容，预计 2021Q2 将重点推进以下方向：</p><ol><li><p><strong>Pacific 正式发布后的稳定化工作</strong>：修复用户反馈的问题，推进 Nautilus/Octopus 用户向 Pacific 迁移。</p></li><li><p><strong>Crimson/SeaStore 功能完善</strong>：PG 流水线并行性合并后的后续优化，SeaStore 未实现的 Future Store API 补全，以及更完整的单元测试覆盖。</p></li><li><p><strong>Orchestrator 功能落地</strong>：HA RGW 服务拆分实施、VIP 服务放置规范扩展、网络配置集成到服务规范的开发和测试。</p></li><li><p><strong>BlueStore OMAP 性能持续优化</strong>：<code>o_node_map</code> 数据结构优化方案落地，缓存管理简化方案实施。</p></li><li><p><strong>Quincy 版本早期规划</strong>：开始收集需求，确定 Quincy 的核心特性方向。</p></li><li><p><strong>Ceph Month 活动举办</strong>：以分散线上会议形式替代 Cephalocon，促进社区交流。</p></li></ol><hr><h2 id="参考文章" tabindex="-1">参考文章 <a class="header-anchor" href="#参考文章" aria-label="Permalink to &quot;参考文章&quot;">​</a></h2><ul><li><a href="/VideoSummary/posts/2021/Ceph_Code_Walkthroughs_-_Librbd_Part_2.html">Ceph Code Walkthroughs: Librbd Part 2</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Crimson_2021-02-23.html">Ceph Crimson 2021-02-23</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStor_OSD_2021-01-26.html">Ceph Crimson/SeaStor OSD 2021-01-26</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStore_2021-03-10.html">Ceph Crimson/SeaStore 2021-03-10</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Crimson_SeaStore_2021-03-17.html">Ceph Crimson/SeaStore 2021-03-17</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Crimson_Seastore_2021-03-23.html">Ceph Crimson/Seastore 2021-03-23</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Developer_Monthly_2021-02-03.html">Ceph Developer Monthly 2021-02-03</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-11.html">Ceph Orchestrator Meeting 2021-03-11</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-16.html">Ceph Orchestrator Meeting 2021-03-16</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-23.html">Ceph Orchestrator Meeting 2021-03-23</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Orchestrator_Meeting_2021-03-30.html">Ceph Orchestrator Meeting 2021-03-30</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Performance_Meeting_2021-03-11.html">Ceph Performance Meeting 2021-03-11</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Performance_Meeting_2021-03-25.html">Ceph Performance Meeting 2021-03-25</a>)</li><li><a href="/VideoSummary/posts/2021/Ceph_Science_Working_Group_2021-03-24.html">Ceph Science Working Group 2021-03-24</a>)</li><li><a href="/VideoSummary/posts/2021/Teuthology_Internals_-_Overview_and_Scheduling.html">Teuthology Internals: Overview and Scheduling</a>)</li><li><a href="/VideoSummary/posts/2021/Teuthology_Training_-_Analyzing_Test_Results.html">Teuthology Training- Analyzing Test Results</a>)</li><li><a href="/VideoSummary/posts/2021/Teuthology_Training_-_Developing_Tests.html">Teuthology Training: Developing Tests</a>)</li><li><a href="/VideoSummary/posts/2021/Teuthology_Training_-_Introduction.html">Teuthology Training: Introduction</a>)</li><li><a href="/VideoSummary/posts/2021/What_s_New_in_Pacific_Ceph_Release_-_Sage_Weil.html">What&#39;s New in Pacific Ceph Release - Sage Weil</a>)</li></ul>',43)])])}const u=r(i,[["render",s]]);export{g as __pageData,u as default};
